async function lireVersion(route) {
  const r = await fetch("/api-pedagogique/v1/" + route);
  const donnees = await r.json();
  return {etat:"ok",version:donnees.version};
}

solution:
async function lireVersion(route) {
  try {
    const r = await fetch("/api-pedagogique/v1/" + route);
    const donnees = await r.json();
    return {etat:"ok",version:donnees.version};
  } catch (erreur) {
    if (erreur.name === "SyntaxError") { return {etat:"json-invalide",version:null}; }
    throw erreur;
  }
}

