async function diagnostiquer(route) {
  const r = await fetch("/api-pedagogique/v1/" + route);
  await r.json();
  return {type:"succès",statut:r.status};
}

solution:
async function diagnostiquer(route) {
  let r;
  try { r = await fetch("/api-pedagogique/v1/" + route); }
  catch (erreur) { return {type:"réseau",statut:null}; }
  if (!r.ok) { return {type:"http",statut:r.status}; }
  try { await r.json(); }
  catch (erreur) { return {type:"json",statut:r.status}; }
  return {type:"succès",statut:r.status};
}

