async function retenterLecture(route) {
  try { const r = await fetch("/api-pedagogique/v1/" + route); await r.json(); return {etat:"succès",tentatives:1}; }
  catch (erreur) { return {etat:"réseau",tentatives:1}; }
}

solution:
async function retenterLecture(route) {
  for (let tentative = 1; tentative <= 2; tentative = tentative + 1) {
    let r;
    try { r = await fetch("/api-pedagogique/v1/" + route); }
    catch (erreur) { if (tentative === 2) { return {etat:"réseau",tentatives:2}; } else { continue; } }
    if (!r.ok) { return {etat:"http",tentatives:tentative}; }
    try { await r.json(); } catch (erreur) { return {etat:"json",tentatives:tentative}; }
    return {etat:"succès",tentatives:tentative};
  }
}

